<?php
/**
 * Plate migration contract — static guard for the console pages.
 *
 * Every migrated page must:
 *   - call the shell helpers and nothing from the retired chrome
 *     (assets-2, bc-header.php, bc-footer.php, bc-style.css);
 *   - keep its body byte-for-byte identical to the pre-migration revision,
 *     except for the retired bootstrap JS bundle the shell replaces;
 *   - keep the short-trans.php partial it had.
 *
 * The expected bodies live in plate_bodies.php (generated by plate_capture.py), so this
 * test needs neither git nor a shell. Runs under `php -n` in CI: no tokenizer, no
 * mbstring, no database.
 */

$checks = 0;
function chk($cond, $label) {
    global $checks;
    $checks++;
    if (!$cond) {
        throw new RuntimeException('migration contract: ' . $label);
    }
}

$root = dirname(__DIR__);
$editions = array('DGV7.0-SAAS', 'DGV7.0-NON-SAAS');

// The retired template chrome. No console page may reference these any more.
// bc-style.css stays: it is the live shared stylesheet the print receipts use.
$retired = array('assets-2/', 'bc-header.php', 'bc-footer.php');

// Pages migrated by hand rather than by plate_migrate.py, because their old chrome was
// not the standard pagetitle shape.
$handDone = array(
    'DGV7.0-SAAS/web/ai-budgeting.php', 'DGV7.0-NON-SAAS/web/ai-budgeting.php',
    'DGV7.0-NON-SAAS/web/AI-Assistant.php', 'DGV7.0-NON-SAAS/web/Pricing.php',
    // No pagetitle block, or a print document with its own action bar.
    'DGV7.0-SAAS/web/APIDocs.php', 'DGV7.0-NON-SAAS/web/APIDocs.php',
    'DGV7.0-SAAS/web/GiftCard.php', 'DGV7.0-NON-SAAS/web/GiftCard.php',
    'DGV7.0-SAAS/web/KYCVerification.php', 'DGV7.0-NON-SAAS/web/KYCVerification.php',
    'DGV7.0-SAAS/web/SiteMap.php', 'DGV7.0-NON-SAAS/web/SiteMap.php',
    'DGV7.0-SAAS/web/ViewBankReceipt.php', 'DGV7.0-NON-SAAS/web/ViewBankReceipt.php',
    'DGV7.0-SAAS/web/ViewCard.php', 'DGV7.0-NON-SAAS/web/ViewCard.php',
    'DGV7.0-SAAS/web/ViewDataBundleCard.php', 'DGV7.0-NON-SAAS/web/ViewDataBundleCard.php',
    'DGV7.0-SAAS/web/ViewElectric.php', 'DGV7.0-NON-SAAS/web/ViewElectric.php',
    'DGV7.0-SAAS/web/ViewNINCard.php', 'DGV7.0-NON-SAAS/web/ViewNINCard.php',
    'DGV7.0-SAAS/web/WebsiteOrderRequest.php', 'DGV7.0-NON-SAAS/web/WebsiteOrderRequest.php',
);

// Pages that intentionally render no console chrome of their own: print targets, raw
// callbacks, partials, and iframe/standalone landings.
$later = array(
    'payhub-success.php', 'guest-payment-complete.php',
    'bc-plate-app.php', 'bc-header.php', 'bc-footer.php', 'short-trans.php',
);

// The retired chrome partials are deleted, not merely unused: the shells own the
// layout now, and the page-level features they injected (AI assistant, referral
// modal, support chat) live in bc_app_widgets() / bc_adm_widgets().
foreach ($editions as $edition) {
    foreach (array('bc-header.php', 'bc-footer.php', 'bc-admin-header.php', 'bc-admin-footer.php',
                   'bc-admin-header-link.php', 'bc-spadmin-header.php', 'bc-spadmin-footer.php',
                   'bc-spadmin-header-link.php') as $partial) {
        chk(!is_file($root . '/' . $edition . '/func/' . $partial), "$edition retired partial func/$partial is deleted");
    }
    $app = file_get_contents($root . '/' . $edition . '/func/bc-plate-app.php');
    chk(strpos($app, 'bc-support-chat-widget.php') !== false, "$edition console shell renders the support chat widget");
    chk(strpos($app, 'ai-assistant.js') !== false, "$edition console shell injects the AI assistant");
    chk(strpos($app, 'referralModal') !== false, "$edition console shell renders the referral modal");
    $adm = file_get_contents($root . '/' . $edition . '/func/bc-plate-admin.php');
    chk(strpos($adm, 'forcePinModal') !== false, "$edition admin shell renders the forced PIN setup");
    chk(strpos($adm, 'quick_set_pin') !== false, "$edition forced PIN setup keeps its AJAX contract");
}

$before = require __DIR__ . '/plate_bodies.php';

foreach ($editions as $edition) {
    $dir = $root . '/' . $edition . '/web';
    chk(is_dir($dir), "$edition web directory exists");

    foreach (glob($dir . '/*.php') as $path) {
        $name = basename($path);
        $rel = $edition . '/web/' . $name;
        $cur = file_get_contents($path);
        $label = $rel;

        // Not on the shell yet: print targets, raw callbacks, and partials.
        if (in_array($name, $later, true)) continue;

        // Signed-out pages sit on the auth shell, not the app shell.
        if (strpos($cur, 'bc_plate_auth_') !== false) {
            chk(strpos($cur, 'bc_plate_auth_top(') !== false, "$label closes on the auth shell");
            continue;
        }

        // Anything else must be on the app shell. If it is not, it has to be a chrome-less
        // endpoint (AJAX, CLI, webhook) rather than a page somebody forgot.
        if (strpos($cur, 'bc_app_head(') === false) {
            chk(strpos($cur, '<!DOCTYPE') === false && strpos($cur, '<html') === false,
                "$label is neither on the shell nor a chrome-less endpoint");
            continue;
        }

        chk(strpos($cur, 'bc_app_head(') !== false, "$label calls bc_app_head(");
        chk(strpos($cur, 'bc_app_foot(') !== false, "$label calls bc_app_foot(");
        foreach ($retired as $token) {
            chk(strpos($cur, $token) === false, "$label has no retired $token");
        }
        if ($name === 'Dashboard.php') continue;

        if (in_array($rel, $handDone, true)) {
            chk(strpos($cur, 'bc_app_sidebar(') !== false, "$label uses the shell sidebar");
            continue;
        }

        chk(isset($before['VTU/' . $rel]), "$label is in the captured set");
        if (!isset($before['VTU/' . $rel])) continue;
        chk(strpos($cur, $before['VTU/' . $rel]) !== false, "$label body is unchanged");
        chk(substr_count($cur, 'short-trans.php') === substr_count($before['VTU/' . $rel], 'short-trans.php'),
            "$label keeps its short-trans partial");
    }
}

echo "plate_migration_test: $checks checks\n";
